## Code Example

```javascript
interface RetryPolicy {
  shouldRetry(error: any, attempt: number, ctx: any): boolean;
  nextDelay(attempt: number, ctx: any): number;
}
class ExponentialWithJitter implements RetryPolicy {
  constructor(private base = 100, private cap = 3000, private jitter = 0.5) {}
  shouldRetry(error: any, attempt: number, ctx: any) {
    return attempt < (ctx.maxAttempts ?? 5) && !!error;
  }
  nextDelay(attempt: number, ctx: any) {
    const exp = Math.min(this.cap, this.base * Math.pow(2, attempt));
    const jitter = Math.random() * this.jitter * exp;
    return exp + jitter;
  }
}
```

